// ===========================================================================
//  Record-store milk crate  —  SDF raymarch, drag to orbit (iMouse).
//
//  Built to hold 12.5" x 12.5" record shaders for a "dig through the vinyl" site.
//  SCALE:  1 world unit = 7 inches   (#define S below)
//  Interior: 13" (W) x 13" (D) x 11" (H)  -> a 12.5" record gets 0.5" of lift
//            clearance side-to-side and peeks ~1.5" above the rim.
//
//  RECORD MOUNT (for later): a record is a thin plane, 12.5" tall x 12.5" wide,
//  facing +z (toward the viewer). In world units a record spans
//     x,y in [-6.25, 6.25]*S = [-0.893, 0.893],  centered at y = 0,
//  thin in z, slotted at successive z and lifted in +y to "pull and view".
//  Front of crate = +z. The empty crate is modeled here; records drop in later.
// ===========================================================================
#define PI 3.14159265
#define S  (1.0/7.0)          // world units per inch

mat2 rot(float a){ float c=cos(a), s=sin(a); return mat2(c,-s,s,c); }

float sdBox(vec3 p, vec3 b){
    vec3 q = abs(p) - b;
    return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}
// square prism, infinite along the 3rd axis; cross-section half-size hxy in the 2 given coords
float sdPrism(vec2 p, vec2 hxy){
    vec2 d = abs(p) - hxy;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}
float hash21(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }

