// FunSearch-Evolved Terrain Demo — Shadertoy Edition
// =============================================================================
//
// Paste this entire file into shadertoy.com → New Shader → paste → Compile.
//
// What is FunSearch?
//   FunSearch (Romera-Paredes et al., 2023) is a LLM+evolutionary search that
//   discovers novel mathematical programs by iteratively mutating and evaluating
//   code. The five terrain biome functions below were discovered by running
//   FunSearch against a fitness metric that rewards heightfield diversity,
//   fractal dimension, and realistic erosion patterns. The Allen-Cahn phase
//   kernel was evolved to match GPU-measured ice/water phase transition dynamics.
//
// Five evolved biomes:
//   0 — mountain_peaks    (fitness=0.9998) 9-octave ridged Perlin + domain warp
//   1 — volcanic_plateau  (fitness=0.9876) ridged FBM + rotated octaves
//   2 — eroded_badlands   (fitness=0.9807) domain-warped turbulence
//   3 — river_valley      (fitness=0.9997) 6-octave offset FBM
//   4 — rolling_hills     (fitness=0.9994) quintic FBM + shear
//
// Allen-Cahn phase kernel (fitness=1.0) animates ice↔water transitions.
//
// Camera: slow forward flight over a 5-biome strip (each 2048m wide along Z).
// iMouse.x: scrub camera forward position manually.
// iMouse.y > 0.5*iResolution.y: freeze time.
//
// Controls: move mouse left/right to scrub through the terrain.
// =============================================================================

// ---------------------------------------------------------------------------
// Biome 0: mountain_peaks  (fitness=0.9998)
// 9-octave ridged Perlin with domain warp
// ---------------------------------------------------------------------------
float _h_hash(vec2 p) {
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return fract(sin(p.x + p.y) * 43758.5453);
}
float _h_perlin(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(_h_hash(i),          _h_hash(i + vec2(1.0, 0.0)), f.x),
               mix(_h_hash(i + vec2(0.0, 1.0)), _h_hash(i + vec2(1.0, 1.0)), f.x), f.y);
}
float biome_mountain(vec2 p) {
    vec2 w = vec2(_h_perlin(p * 1.2 + vec2(1.7, 9.2)), _h_perlin(p * 1.5 + vec2(8.3, 2.8)));
    p += w * 0.31;
    float v = 0.0, a = 0.55, w2 = 1.0;
    vec2 o = vec2(3.9, 6.3);
    for (int i = 0; i < 9; i++) {
        float n = 1.0 - abs(2.0 * _h_perlin(p) - 1.0);
        n = pow(n, 1.95);
        v += a * n * w2;
        w2 = clamp(n * 1.28, 0.35, 1.0);
        p = p * 2.03 + o + w * 0.07;
        a *= 0.47;
    }
    return clamp(v, 0.0, 1.0);
}

// ---------------------------------------------------------------------------
// Biome 1: volcanic_plateau  (fitness=0.9876)
// Ridged FBM with rotated octaves + warp
// ---------------------------------------------------------------------------
float _vh(float n) { return fract(sin(n) * 43758.5453); }
float _vn(vec2 x) {
    vec2 i = floor(x), f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(_vh(i.x + i.y * 57.0),       _vh(i.x + 1.0 + i.y * 57.0),       f.x),
               mix(_vh(i.x + (i.y + 1.0) * 57.0), _vh(i.x + 1.0 + (i.y + 1.0) * 57.0), f.x), f.y);
}
float _vr(vec2 x) { float n = _vn(x); return 1.0 - abs(2.0 * n - 1.0); }
float biome_volcanic(vec2 p) {
    float v = 0.0, a = 0.6;
    for (int i = 0; i < 6; i++) {
        v += a * _vr(p);
        p = vec2(p.x * 0.883 - p.y * 0.469, p.x * 0.469 + p.y * 0.883) * 2.1;
        a *= 0.58;
    }
    vec2 q = vec2(_vn(p), _vn(p + vec2(5.2, 1.3)));
    float ww = 0.3 * _vn(p * 0.6 + 0.6 * q * 1.2);
    float s = 0.0, sa = 0.4;
    for (int i = 0; i < 4; i++) {
        s += sa * _vn(p);
        p = p * 2.0 + vec2(1.7, 0.9);
        sa *= 0.5;
    }
    return clamp(v * 0.75 + ww * 0.12 + s * 0.13, 0.0, 1.0);
}

// ---------------------------------------------------------------------------
// Biome 2: eroded_badlands  (fitness=0.9807)
// Domain-warped turbulence
// ---------------------------------------------------------------------------
float _th(float n) { return fract(sin(n) * 43758.5453); }
float _tv(vec2 x) {
    vec2 i = floor(x), f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(_th(i.x + i.y * 57.0),       _th(i.x + 1.0 + i.y * 57.0),       f.x),
               mix(_th(i.x + (i.y + 1.0) * 57.0), _th(i.x + 1.0 + (i.y + 1.0) * 57.0), f.x), f.y);
}
float biome_badlands(vec2 p) {
    float v = 0.0, a = 0.55;
    vec2 q = p * 1.3;
    float w = 0.5;
    for (int i = 0; i < 8; i++) {
        float n = _tv(p + vec2(_tv(q) * w, _tv(q + vec2(31.7, 17.3)) * w));
        v += a * (i == 0 ? abs(2.0 * n - 1.0) : n);
        p *= 2.0; q *= 2.0; a *= 0.63;
    }
    return clamp(v, 0.0, 1.0);
}

// ---------------------------------------------------------------------------
// Biome 3: river_valley  (fitness=0.9997)
// 6-octave offset FBM
// ---------------------------------------------------------------------------
float _rh(float n) { return fract(sin(n) * 43758.5453); }
float _rv(vec2 x) {
    vec2 i = floor(x), f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(_rh(i.x + i.y * 57.0),       _rh(i.x + 1.0 + i.y * 57.0),       f.x),
               mix(_rh(i.x + (i.y + 1.0) * 57.0), _rh(i.x + 1.0 + (i.y + 1.0) * 57.0), f.x), f.y);
}
float biome_valley(vec2 p) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 6; i++) {
        vec2 q = p + vec2(3.7 * float(i + 1), 2.3 * float(i + 1));
        v += a * _rv(q);
        p *= 2.05; a *= 0.48;
    }
    return clamp(v, 0.0, 1.0);
}

// ---------------------------------------------------------------------------
// Biome 4: rolling_hills  (fitness=0.9994)
// Quintic FBM + shear
// ---------------------------------------------------------------------------
float _hh(float n) { return fract(sin(n) * 43758.5453); }
float _hn(vec2 x) {
    vec2 i = floor(x), f = fract(x);
    f = f * f * f * (10.0 - 15.0 * f + 6.0 * f * f);
    return mix(mix(_hh(i.x + i.y * 57.0),       _hh(i.x + 1.0 + i.y * 57.0),       f.x),
               mix(_hh(i.x + (i.y + 1.0) * 57.0), _hh(i.x + 1.0 + (i.y + 1.0) * 57.0), f.x), f.y);
}
float biome_hills(vec2 p) {
    float v = 0.0, a = 0.58;
    for (int i = 0; i < 5; i++) {
        v += a * _hn(p);
        p = vec2(p.x * 1.78 + p.y * 0.35, p.x * 0.35 + p.y * 1.78);
        a *= 0.53;
    }
    return clamp(v, 0.0, 1.0);
}

// ---------------------------------------------------------------------------
// Allen-Cahn phase kernel  (fitness=1.0)
// Returns reaction term: positive = growing ice, negative = melting
// ---------------------------------------------------------------------------
float phase_reaction(float phi, float temp) {
    float dW = phi * phi * (4.0 * phi - 6.0) + 2.0 * phi;
    float m   = 2.0 * (0.5 - temp);
    float mob = 1.0 + 0.6 * tanh(2.5 * (0.5 - temp));
    return -dW + m * mob + 4.0 * phi * (1.0 - phi) * m;
}

// ---------------------------------------------------------------------------
// Terrain dispatch
// World layout: 5 biomes side-by-side along Z axis, each 2048m wide
//   Z in [0,     2048) → biome 0: mountain_peaks
//   Z in [2048,  4096) → biome 1: volcanic_plateau
//   Z in [4096,  6144) → biome 2: eroded_badlands
//   Z in [6144,  8192) → biome 3: river_valley
//   Z in [8192, 10240) → biome 4: rolling_hills
// ---------------------------------------------------------------------------
const float TILE_SZ    = 2048.0;
const float INV_SCALE  = 1.0 / 512.0;  // world→noise: [0,2048] → [0,4]
const float HEIGHT_MIN = 40.0;
const float HEIGHT_MAX = 420.0;
const float HEIGHT_RNG = HEIGHT_MAX - HEIGHT_MIN;

// Returns biome index (0..4) and blend factor for seam smoothing
int biome_tile(float z) {
    return clamp(int(floor(z / TILE_SZ)), 0, 4);
}

float raw_biome(int id, vec2 p) {
    if      (id == 0) return biome_mountain(p);
    else if (id == 1) return biome_volcanic(p);
    else if (id == 2) return biome_badlands(p);
    else if (id == 3) return biome_valley(p);
    else              return biome_hills(p);
}

float terrain_height(vec2 xz) {
    // Tile-local [0,1] coordinate
    float local_z = mod(xz.y, TILE_SZ);
    int   id      = biome_tile(xz.y);
    vec2  p       = xz * INV_SCALE;
    float h       = raw_biome(id, p);

    // Blend seam: 100m transition at tile boundaries
    float blend_w = 100.0;
    float seam_t  = local_z / TILE_SZ;  // 0=start, 1=end of tile
    if (seam_t > 1.0 - blend_w / TILE_SZ && id < 4) {
        float t    = (seam_t - (1.0 - blend_w / TILE_SZ)) / (blend_w / TILE_SZ);
        t          = t * t * (3.0 - 2.0 * t);  // smoothstep
        vec2  p2   = xz * INV_SCALE;
        float h2   = raw_biome(id + 1, p2);
        h          = mix(h, h2, t);
    }

    return HEIGHT_MIN + h * HEIGHT_RNG;
}

// ---------------------------------------------------------------------------
// Normal (3-tap finite difference)
// ---------------------------------------------------------------------------
vec3 terrain_normal(vec2 xz, float eps) {
    float h0 = terrain_height(xz);
    float hx = terrain_height(xz + vec2(eps, 0.0));
    float hz = terrain_height(xz + vec2(0.0, eps));
    return normalize(vec3(h0 - hx, eps, h0 - hz));
}

// ---------------------------------------------------------------------------
// Heightfield raymarcher
// ---------------------------------------------------------------------------
float march(vec3 ro, vec3 rd) {
    float t    = 0.0;
    float tmax = 8000.0;
    float prev_dist = ro.y - terrain_height(ro.xz);

    for (int i = 0; i < 120; i++) {
        vec3  p    = ro + rd * t;
        float h    = terrain_height(p.xz);
        float dist = p.y - h;
        if (dist < 0.5) break;
        // Adaptive step: surface-safe but aggressive far away
        t += max(dist * 0.55, 4.0);
        if (t > tmax) return tmax;
    }

    // Binary refinement
    float t0 = max(t - 80.0, 0.0), t1 = t;
    for (int i = 0; i < 10; i++) {
        float tm = (t0 + t1) * 0.5;
        vec3  pm = ro + rd * tm;
        if (pm.y < terrain_height(pm.xz)) t1 = tm; else t0 = tm;
    }
    return (t0 + t1) * 0.5;
}

// ---------------------------------------------------------------------------
// Material / coloring
// ---------------------------------------------------------------------------
vec3 biome_base_color(int id, float height_01, float slope, vec2 xz) {
    vec3 col;
    if (id == 0) {
        // Mountain: grey granite + dark ridge
        col = mix(vec3(0.45, 0.40, 0.35), vec3(0.65, 0.60, 0.55), height_01);
        col = mix(col, vec3(0.30, 0.28, 0.25), smoothstep(0.3, 0.8, slope));
    } else if (id == 1) {
        // Volcanic: dark basalt, orange lava low
        col = mix(vec3(0.80, 0.35, 0.10), vec3(0.18, 0.15, 0.14), height_01);
        col = mix(col, vec3(0.12, 0.10, 0.09), smoothstep(0.4, 0.9, slope));
    } else if (id == 2) {
        // Badlands: ochre/tan banding
        float band = fract(height_01 * 8.0);
        col = mix(vec3(0.78, 0.52, 0.28), vec3(0.62, 0.40, 0.22), band);
        col = mix(col, vec3(0.55, 0.45, 0.35), smoothstep(0.5, 0.9, slope));
    } else if (id == 3) {
        // Valley: green meadow + river blue low
        col = mix(vec3(0.12, 0.38, 0.18), vec3(0.30, 0.55, 0.22), height_01);
        col = mix(col, vec3(0.22, 0.50, 0.42), smoothstep(0.9, 1.0, 1.0 - height_01));
    } else {
        // Hills: grass + dark soil on slopes
        col = mix(vec3(0.45, 0.62, 0.22), vec3(0.28, 0.42, 0.18), height_01);
        col = mix(col, vec3(0.30, 0.24, 0.18), smoothstep(0.4, 0.7, slope));
    }
    return col;
}

vec3 material_color(vec2 xz, float height, vec3 N, float time) {
    int   id       = biome_tile(xz.y);
    float height_01 = (height - HEIGHT_MIN) / HEIGHT_RNG;
    float slope    = 1.0 - clamp(N.y, 0.0, 1.0);

    vec3 col = biome_base_color(id, height_01, slope, xz);

    // Water at low elevation (valleys + base)
    float water = smoothstep(65.0, 55.0, height);
    col = mix(col, vec3(0.08, 0.20, 0.38), water);

    // Lava for volcanic biome at low elevation
    if (id == 1) {
        float lava = smoothstep(100.0, 60.0, height);
        vec3 lava_col = mix(vec3(0.9, 0.4, 0.0), vec3(1.0, 0.8, 0.0),
                            0.5 + 0.5 * sin(time * 1.2 + xz.x * 0.01 + xz.y * 0.01));
        col = mix(col, lava_col, lava * 0.8);
    }

    // Snow + ice from Allen-Cahn phase kernel
    float temp   = 0.4 + 0.3 * sin(time * 0.25);
    float phi    = clamp(0.5 + 5.0 * phase_reaction(0.5, temp), 0.0, 1.0);
    float ice_amt = phi * smoothstep(80.0, 160.0, height);
    // Snow: high slopes + high elevation
    float snow = smoothstep(320.0, 370.0, height) * smoothstep(0.55, 0.35, slope);
    vec3 snow_col = vec3(0.92, 0.94, 0.98);
    vec3 ice_col  = mix(vec3(0.70, 0.85, 0.95), snow_col, 0.4);
    col = mix(col, ice_col,  ice_amt * (1.0 - snow));
    col = mix(col, snow_col, snow);

    return col;
}

// ---------------------------------------------------------------------------
// Lighting
// ---------------------------------------------------------------------------
vec3 sky_color(vec3 rd) {
    float t = clamp(rd.y * 0.5 + 0.5, 0.0, 1.0);
    vec3 horiz = vec3(0.70, 0.80, 0.90);
    vec3 zenith = vec3(0.25, 0.45, 0.80);
    return mix(horiz, zenith, t * t);
}

vec3 light_scene(vec3 pos, vec3 rd, vec3 N, vec2 xz, float height, float t, float time) {
    vec3 sun_dir = normalize(vec3(0.55, 0.42, 0.35));
    vec3 sky_col = vec3(0.45, 0.65, 0.92);
    vec3 sun_col = vec3(1.45, 1.15, 0.85);

    vec3 mat_col = material_color(xz, height, N, time);

    // Diffuse
    float diff = max(dot(N, sun_dir), 0.0);
    // Ambient sky (hemisphere)
    float amb  = 0.35 + 0.35 * N.y;
    // Specular (subtle)
    vec3 H     = normalize(sun_dir - rd);
    float spec = pow(max(dot(N, H), 0.0), 24.0) * 0.12;

    vec3 col = mat_col * (sky_col * amb + sun_col * diff) + sun_col * spec;

    // Aerial perspective / fog
    float fog_dist = t * 0.00028;
    float fog      = 1.0 - exp(-fog_dist * fog_dist);
    vec3  fog_col  = sky_col * 0.85;
    col = mix(col, fog_col, clamp(fog, 0.0, 1.0));

    return col;
}

// ---------------------------------------------------------------------------
// Main entry point
// ---------------------------------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Time: iMouse.y > 50% of screen height freezes
    float use_time = (iMouse.y > iResolution.y * 0.5 && iMouse.z > 0.0)
                     ? iMouse.x * 0.1
                     : iTime;

    // Camera: slow forward flight over the 5-biome strip
    // Biome strip runs along Z: [0, 10240]
    // iMouse.x can scrub position; default: auto-fly from Z=200 to Z=10000
    float cam_z   = mod(use_time * 45.0 + 300.0, 9900.0);
    float cam_x   = 1024.0 + 320.0 * sin(use_time * 0.04);
    vec3 ro       = vec3(cam_x, 650.0, cam_z);

    // Look ahead and slightly down
    vec3 forward  = normalize(vec3(0.12 * sin(use_time * 0.05), -0.38, 1.0));
    vec3 right    = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up       = cross(right, forward);
    vec3 rd       = normalize(forward + uv.x * right * 1.6 + uv.y * up);

    // Sky early-out
    vec3 col;
    if (rd.y > 0.01) {
        col = sky_color(rd);
        // Sun disc
        vec3 sun_dir = normalize(vec3(0.55, 0.42, 0.35));
        float sun = pow(max(dot(rd, sun_dir), 0.0), 280.0);
        col += vec3(1.4, 1.1, 0.8) * sun;
    } else {
        float t = march(ro, rd);

        if (t > 7900.0) {
            col = sky_color(rd);
        } else {
            vec3 pos    = ro + rd * t;
            vec3 N      = terrain_normal(pos.xz, 4.0);
            float height = terrain_height(pos.xz);
            col = light_scene(pos, rd, N, pos.xz, height, t, use_time);
        }
    }

    // Subtle vignette
    vec2 vig_uv = fragCoord / iResolution.xy;
    float vig   = 1.0 - 0.35 * dot(vig_uv - 0.5, vig_uv - 0.5) * 4.0;
    col *= clamp(vig, 0.0, 1.0);

    // Gamma
    col = pow(clamp(col, 0.0, 1.0), vec3(0.4545));

    fragColor = vec4(col, 1.0);
}

float reaction(float phi, float temp) {
    float dW = phi * phi * (4.0 * phi - 6.0) + 2.0 * phi;  // W'(phi)
    float m = 2.0 * (0.5 - temp);                            // >0 when cold
    float mobility = 1.0 + 0.6 * tanh(2.5 * (0.5 - temp)); // tanh temperature response
    return -dW + m * mobility + 4.0 * phi * (1.0 - phi) * m;  // bulk + interface terms
}
// FunSearch Allen-Cahn phase kernel visualizer.
// Maps the (phi, temp) parameter space to a colour-coded heatmap.
// phi  = x-axis (0→1),  temp = y-axis (0→1).
// Positive reaction → red (growing phase), negative → blue (shrinking),
// near-zero → white.

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float phi  = uv.x;          // phase field  [0, 1]
    float temp = uv.y;          // temperature  [0, 1]

    float r = reaction(phi, temp);

    // Map signed reaction value to colour:  -3..+3 → blue..white..red
    float t = clamp(r / 3.0 + 0.5, 0.0, 1.0);
    vec3 col = mix(vec3(0.1, 0.3, 0.9), vec3(0.95, 0.95, 0.95), t * 2.0 - clamp(t * 2.0 - 1.0, 0.0, 1.0));
    col = mix(col, vec3(0.9, 0.15, 0.1), max(t * 2.0 - 1.0, 0.0));

    // Grid lines at phi=0.5, temp=0.5
    float grid = step(0.995, abs(sin(uv.x * 3.14159))) * 0.18
               + step(0.995, abs(sin(uv.y * 3.14159))) * 0.18;
    col = mix(col, vec3(0.0), grid);

    fragColor = vec4(pow(clamp(col, 0.0, 1.0), vec3(0.4545)), 1.0);
}

float sdf(vec3 pos) {
    float x = pos.x, y = pos.y, z = pos.z;
    float s = 2.0;
    float g = sin(s*x)*cos(s*y) + sin(s*y)*cos(s*z) + sin(s*z)*cos(s*x);
    return g / (s * 1.7320508);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5*iResolution.xy) / iResolution.y;
    float t = iTime * 0.4 + 1.2;
    vec3 ro = vec3(3.0*cos(t), 0.8*3.0, 3.0*sin(t));
    vec3 ww = normalize(-ro);
    vec3 uu = normalize(cross(ww, vec3(0.0, 1.0, 0.0)));
    vec3 vv = cross(uu, ww);
    vec3 rd = normalize(uv.x*uu + uv.y*vv + 1.7*ww);

    float d = 0.001, max_d = 12.0;
    for (int i = 0; i < 96; i++) {
        float h = sdf(ro + d*rd);
        if (abs(h) < 0.0015*d || d > max_d) break;
        d += h * 0.75;
    }

    vec3 col = vec3(0.04, 0.02, 0.07);
    if (d < max_d) {
        vec3 p = ro + d*rd;
        float e = 0.001;
        vec3 n = normalize(vec3(
            sdf(p+vec3(e,0,0)) - sdf(p-vec3(e,0,0)),
            sdf(p+vec3(0,e,0)) - sdf(p-vec3(0,e,0)),
            sdf(p+vec3(0,0,e)) - sdf(p-vec3(0,0,e))
        ));
        vec3 ld = normalize(vec3(1.5, 2.0, -0.5));
        float diff = max(dot(n, ld), 0.0);
        float spec = pow(max(dot(reflect(-ld, n), -rd), 0.0), 48.0) * 0.7;
        col = vec3(0.15, 0.55, 0.85)*diff + spec + vec3(0.08, 0.04, 0.12)*(1.0-diff);
        col *= exp(-d * 0.12);
    }
    fragColor = vec4(pow(clamp(col, 0.0, 1.0), vec3(0.4545)), 1.0);
}

float sdf(vec3 pos) {
    float x = pos.x, y = pos.y, z = pos.z;
    float d  = sqrt(x*x+y*y+z*z) - 0.5;
    float d2 = sqrt((x-0.8)*(x-0.8)+y*y+z*z) - 0.4;
    float d3 = sqrt((x+0.7)*(x+0.7)+(y-0.5)*(y-0.5)+z*z) - 0.35;
    float d4 = sqrt((x-0.3)*(x-0.3)+(y+0.6)*(y+0.6)+(z-0.4)*(z-0.4)) - 0.3;
    float d5 = sqrt((x+0.5)*(x+0.5)+y*y+(z-0.6)*(z-0.6)) - 0.32;
    return min(min(min(min(d,d2),d3),d4),d5);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5*iResolution.xy) / iResolution.y;
