    if (d < max_d) {
        vec3 p = ro + d*rd;
        float e = 0.001;
        vec3 n = normalize(vec3(
            sdf(p+vec3(e,0,0)) - sdf(p-vec3(e,0,0)),
            sdf(p+vec3(0,e,0)) - sdf(p-vec3(0,e,0)),
            sdf(p+vec3(0,0,e)) - sdf(p-vec3(0,0,e))
        ));
        vec3 ld = normalize(vec3(1.5, 2.0, -0.5));
        float diff = max(dot(n, ld), 0.0);
        float spec = pow(max(dot(reflect(-ld, n), -rd), 0.0), 48.0) * 0.7;
        col = vec3(0.15, 0.55, 0.85)*diff + spec + vec3(0.08, 0.04, 0.12)*(1.0-diff);
        col *= exp(-d * 0.12);
    }
    fragColor = vec4(pow(clamp(col, 0.0, 1.0), vec3(0.4545)), 1.0);
}

float sdf(vec3 pos) {
    float x = pos.x, y = pos.y, z = pos.z;
    const float R = 0.6, rm = 0.35, tube = 0.15;
    const float pi2 = 6.28318530, p = 2.0, q = 3.0;
    float best_d = 1e9, best_t = 0.0;
    for (int i = 0; i < 48; i++) {
        float t = pi2 * float(i) / 48.0;
        float rr = R + rm*cos(q*t);
        float kx = rr*cos(p*t), ky = rr*sin(p*t), kz = rm*sin(q*t);
        float dx = x-kx, dy = y-ky, dz = z-kz;
        float d = sqrt(dx*dx+dy*dy+dz*dz);
        if (d < best_d) { best_d = d; best_t = t; }
    }
    float arc_dense = pi2 / (p * 200.0);
    for (int i = -12; i <= 12; i++) {
        float t = best_t + float(i)*arc_dense;
        float rr = R + rm*cos(q*t);
        float kx = rr*cos(p*t), ky = rr*sin(p*t), kz = rm*sin(q*t);
        float dx = x-kx, dy = y-ky, dz = z-kz;
        float d = sqrt(dx*dx+dy*dy+dz*dz);
        if (d < best_d) best_d = d;
    }
    return best_d - tube;
}

