float sdf(vec3 pos) {
    float x = pos.x, y = pos.y, z = pos.z;
    // Domain-warped gyroid approximation
    float tx = x + 0.2 * sin(4.0 * y + z * 0.5);
    float ty = y + 0.2 * sin(4.0 * z + x * 0.5);
    float tz = z + 0.2 * sin(4.0 * x + y * 0.5);

    float s = 2.8;
    float f = sin(s * tx) * cos(s * ty) 
            + sin(s * ty) * cos(s * tz) 
            + sin(s * tz) * cos(s * tx);

    float grad = s * 1.7320508;
    return abs(f) / grad - 0.12;
}

