float sdf(vec3 pos) {
    float x = pos.x, y = pos.y, z = pos.z;
    // Domain twist for richer structure
    float a = 0.1 * z;
    float ca = cos(a), sa = sin(a);
    float xw = x*ca - y*sa;
    float yw = x*sa + y*ca;

    // Multi-scale gyroid: coarse + fine blended
    float s1 = 3.0, s2 = 5.0;
    float f1 = sin(s1*xw)*cos(s1*yw) + sin(s1*yw)*cos(s1*z) + sin(s1*z)*cos(s1*xw);
    float f2 = sin(s2*xw)*cos(s2*yw) + sin(s2*yw)*cos(s2*z) + sin(s2*z)*cos(s2*xw);

    // Lipschitz-normalised signed distance (gradient bound = s*sqrt(3))
    float d1 = abs(f1) / (s1 * 1.7320508);
    float d2 = abs(f2) / (s2 * 1.7320508);

    // Smooth union of two scales
    float k = 0.08;
    float h = max(k - abs(d1 - d2), 0.0) / k;
    float d = min(d1, d2) - h*h*k*0.25;

    return d - 0.1;
}

