float sph_kernel(float r, float h) {
    float q = r / h;
    if (q >= 1.0) return 0.0;
    float m = 1.0 - q;
    float sigma = 1536.0 / (478.0 * 3.14159265 * h * h * h);
    float poly = 1.0 + 5.0 * q + 10.0 * q * q + 10.0 * q * q * q + 
                 5.0 * q * q * q * q + q * q * q * q * q;
    float m5 = m * m; m5 *= m5 * m;
    return sigma * m5 * poly;
}
// FunSearch SPH kernel visualizer.
// Plots W(r, h=1) as a function of r/h.
// x-axis: r/h ∈ [0, 1.2],  y-axis: normalised W value.
// The compact support cutoff at r/h = 1 is marked with a dashed line.

float sampleW(float rh) {
    float h = 1.0;
    return sph_kernel(rh * h, h);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec3 col = vec3(0.08, 0.08, 0.12);

    float rh_range = 1.3;
    float rh = uv.x * rh_range;

    // Evaluate the curve value at this column
    float W_here = sampleW(rh);
    float W_max  = sampleW(0.0);
    float W_norm = (W_max > 0.0) ? W_here / W_max : 0.0;

    // Plot curve: draw band around the normalised value
    float curve_y = W_norm;
    float dist = abs(uv.y - curve_y);
    float line_w = 2.0 / iResolution.y;
    col = mix(vec3(0.2, 0.75, 0.95), col, smoothstep(0.0, line_w * 2.0, dist));

    // Fill under the curve
    if (uv.y < curve_y) {
        col = mix(col, vec3(0.1, 0.35, 0.55), 0.35);
    }

    // Dashed vertical at r/h = 1.0
    float cutoff_x = 1.0 / rh_range;
    float cx = abs(uv.x - cutoff_x);
    float dash = step(0.5, fract(uv.y * 14.0));
    col = mix(col, vec3(0.95, 0.65, 0.1), dash * (1.0 - smoothstep(0.0, 3.0 / iResolution.x, cx)));

    // Axis labels (grid lines)
    col = mix(col, vec3(0.35), step(uv.y, 0.012) + step(uv.x, 0.012 * iResolution.y / iResolution.x));

    fragColor = vec4(pow(clamp(col, 0.0, 1.0), vec3(0.4545)), 1.0);
}

float _rh_hash(float n) { return fract(sin(n) * 43758.5453); }
float _rh_vnoise(vec2 x) {
    vec2 i = floor(x); vec2 f = fract(x); f = f*f*f*(10.0 - 15.0*f + 6.0*f*f);
    float n00 = _rh_hash(i.x + i.y * 57.0); float n10 = _rh_hash(i.x + 1.0 + i.y * 57.0);
    float n01 = _rh_hash(i.x + (i.y+1.0) * 57.0); float n11 = _rh_hash(i.x + 1.0 + (i.y+1.0) * 57.0);
    return mix(mix(n00, n10, f.x), mix(n01, n11, f.x), f.y);
}
float terrain(vec2 p) {
    float v = 0.0, a = 0.58;
    for (int i = 0; i < 5; i++) {
        v += a * _rh_vnoise(p);
        p = vec2(p.x * 1.78 + p.y * 0.35, p.x * 0.35 + p.y * 1.78);
        a *= 0.53;
    }
    return clamp(v, 0.0, 1.0);
}
// FunSearch: biome=rolling_hills, fitness=0.9994
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    vec3 ro = vec3(1024.0 + 300.0*sin(iTime*0.1), 450.0, iTime*10.0);
    vec3 ta = ro + vec3(0.0, -160.0, 500.0);
    vec3 ww = normalize(ta - ro);
    vec3 uu = normalize(cross(ww, vec3(0.0,1.0,0.0)));
    vec3 rd = normalize(uv.x*uu + uv.y*cross(uu,ww) + 1.4*ww);
    vec3 sun = normalize(vec3(0.6, 0.4, 0.3));
    vec3 col = mix(vec3(0.3,0.5,0.82), vec3(0.9,0.8,0.7), pow(max(dot(rd,sun),0.0),4.0));
    float t = 5.0;
    for (int i = 0; i < 80; i++) {
        vec3 p = ro + rd*t;
        float h = terrain(p.xz * 0.0025) * 360.0 + 40.0;
        float diff = p.y - h;
        if (diff < 0.5 || t > 3500.0) break;
        t += max(diff * 0.6, 3.0);
    }
    if (t < 3490.0) {
        vec3 p = ro + rd*t;
        vec2 xz = p.xz * 0.0025;
        float e = 0.01;
        vec3 n = normalize(vec3(terrain(xz-vec2(e,0.0))-terrain(xz+vec2(e,0.0)),
                                2.0*e,
                                terrain(xz-vec2(0.0,e))-terrain(xz+vec2(0.0,e))));
        float h = terrain(xz)*360.0+40.0;
        float slope = 1.0 - n.y;
        vec3 mat = mix(vec3(0.28,0.46,0.18), vec3(0.38,0.30,0.22), clamp(slope*2.0,0.0,1.0));
        mat = mix(mat, vec3(0.88,0.94,0.98), smoothstep(305.0,375.0,h));
        mat = mix(mat, vec3(0.18,0.32,0.54), smoothstep(80.0,52.0,h));
        col = mat*(max(dot(n,sun),0.0)*vec3(1.35,1.1,0.85)+max(n.y,0.0)*vec3(0.1,0.16,0.26));
        col = mix(col, vec3(0.52,0.66,0.84), 1.0-exp(-t*0.00022));
    }
    fragColor = vec4(pow(clamp(col,0.0,1.0), vec3(0.4545)), 1.0);
}
